using System.Collections.Generic;
using UnityEngine;
namespace NakiLegend.Prototype {
 public sealed partial class NakiPrototype {
  private readonly Dictionary<int,Sprite> forgeFixtureSprites=new Dictionary<int,Sprite>();
  private readonly List<Rect> forgeFenceShots=new List<Rect>();private int forgeFenceRoom=-1;
  private Sprite ForgeFixture(int index){Sprite s;if(forgeFixtureSprites.TryGetValue(index,out s)&&s!=null)return s;var t=Resources.Load<Texture2D>("NakiArt/FireWorkshop/readability-v2");if(t==null)throw new System.InvalidOperationException("Missing forge railing and trench artwork");t.filterMode=FilterMode.Point;Rect[] regions={new Rect(60,200,850,300),new Rect(1100,0,155,560),new Rect(60,670,850,245)};Rect r=regions[index];r=new Rect(r.x*t.width/1536,(1024-r.yMax)*t.height/1024,r.width*t.width/1536,r.height*t.height/1024);s=Sprite.Create(t,r,Vector2.one*.5f,r.height,0,SpriteMeshType.FullRect);ownedAssets.Add(s);forgeFixtureSprites[index]=s;return s;}
  private void ClearForgeFenceShots(){if(forgeFenceRoom==currentRoom)foreach(Rect r in forgeFenceShots)projectileObstacles.Remove(r);forgeFenceShots.Clear();forgeFenceRoom=currentRoom;}
  private void TrackCampCollision(Vector2 at,Vector2 size,bool blockShots){Rect r=new Rect(at-size*.5f,size);iceCampBlocks.Add(r);obstacles.Add(r);if(blockShots){forgeFenceShots.Add(r);projectileObstacles.Add(r);}}
  private void DrawCampRailing(Vector2 at,Vector2 size){bool vertical=size.y>size.x;var o=Stretch("Iron shelter safety railing",ForgeFixture(vertical?1:0),at,vertical?new Vector2(.36f,size.y+.15f):new Vector2(size.x+.12f,.55f),iceSampleMode?new Color(.8f,.92f,1):Color.white,DepthAt(at.y));o.transform.SetParent(chapterFocus.transform,true);TrackCampCollision(at,size,true);}
  private int WorkshopGoal {get{return woodlandMode?WoodlandGoal:!fireChapterMode||journeyRooms.Count<30||journeyRooms[currentRoom].stage==0?-1:journeyRooms[currentRoom].stage==2?(!fireHeartRecovered?42:(fireEvacuation&1)==0?43:fireEvacuation!=3?44:30):!forgeRescued?20:!forgeBridgeOpen?23:!journeyRooms[27].cleared?27:29;}}
  private int WorkshopNextRoom(){int goal=WorkshopGoal;if(goal<0||goal==currentRoom)return -1;var queue=new Queue<int>();var first=new Dictionary<int,int>();queue.Enqueue(currentRoom);first[currentRoom]=-1;while(queue.Count>0){int id=queue.Dequeue();foreach(int link in journeyRooms[id].links){if(first.ContainsKey(link)||ExplorationDoorLocked(id,NeighborDirection(journeyRooms[id],journeyRooms[link])))continue;first[link]=id==currentRoom?link:first[id];if(link==goal)return first[link];queue.Enqueue(link);}}return -1;}
  private void BuildWorkshopGuide(RoomNode n){UpdateFlowGuide();}
  private string WorkshopGateReason(int room,int direction){if(woodlandMode){foreach(int link in journeyRooms[room].links)if(link==18&&NeighborDirection(journeyRooms[room],journeyRooms[link])==direction&&(!chapterRanger||WoodClues<2))return !chapterRanger?"先清理看守并打开采种人的牢笼（M 查看目标）":"调查封丝树孔、空果壳或休眠种根中的两处（M 查看目标）";return null;}if(!fireChapterMode)return null;foreach(int link in journeyRooms[room].links)if(link==27&&NeighborDirection(journeyRooms[room],journeyRooms[link])==direction){if(!forgeRescued)return "炉道封锁：先到工匠避难间，转动绞盘救出阿铎（M 查看目标）";if(!forgeBridgeOpen)return "阿铎已获救：回到撤离桥头，靠近左侧绞盘按 F 放桥，巨匠房才会解锁";}return null;}
  private bool ExplainNearbyWorkshopGate(){if((!fireChapterMode&&!woodlandMode)||!journeyRooms[currentRoom].cleared)return false;for(int d=0;d<4;d++){string reason=WorkshopGateReason(currentRoom,d);if(reason!=null&&Vector2.Distance(position,DoorPoint(d))<1.8f){JourneyHint(reason);return true;}}return false;}
 }
}
